defmodule JoobQ.TransportTest do
  use ExUnit.Case, async: true

  alias JoobQ.{Error, Transport}

  setup do
    bypass = Bypass.open()
    name = :"joobq_#{System.unique_integer([:positive])}"
    start_supervised!({JoobQ, name: name, url: "http://localhost:#{bypass.port}", token: "t0ken"})
    {:ok, bypass: bypass, name: name}
  end

  test "sends the token and JSON, and decodes the answer", %{bypass: bypass, name: name} do
    Bypass.expect_once(bypass, "POST", "/api/v1/sdk/ping", fn conn ->
      assert Plug.Conn.get_req_header(conn, "authorization") == ["Bearer t0ken"]
      assert Plug.Conn.get_req_header(conn, "content-type") == ["application/json"]
      {:ok, body, conn} = Plug.Conn.read_body(conn)
      assert Jason.decode!(body) == %{"a" => 1}
      Plug.Conn.resp(conn, 201, ~s({"ok":true}))
    end)

    assert Transport.request(name, :post, "/ping", %{a: 1}) == {:ok, %{"ok" => true}}
  end

  test "names the SDK and its version on every call", %{bypass: bypass, name: name} do
    Bypass.expect_once(bypass, "GET", "/api/v1/sdk/ping", fn conn ->
      assert Plug.Conn.get_req_header(conn, "x-joobq-sdk") == ["elixir/" <> JoobQ.sdk_version()]
      Plug.Conn.resp(conn, 200, ~s({}))
    end)

    assert Transport.request(name, :get, "/ping") == {:ok, %{}}
  end

  test "answers the gateway's error once, without retrying a 5xx", %{bypass: bypass, name: name} do
    Bypass.expect_once(bypass, "POST", "/api/v1/sdk/ping", fn conn ->
      Plug.Conn.resp(
        conn,
        503,
        ~s({"error":{"code":"sdk_token_not_configured","message":"none"}})
      )
    end)

    assert {:error, %Error{reason: :unavailable, status: 503}} =
             Transport.request(name, :post, "/ping", %{})
  end

  test "a gateway that does not answer is a transport error", %{bypass: bypass, name: name} do
    Bypass.down(bypass)

    assert {:error, %Error{reason: :transport, status: nil}} =
             Transport.request(name, :get, "/ping")
  end

  test "an instance that is not started is refused" do
    assert_raise ArgumentError, ~r/not started/, fn -> Transport.request(:nope, :get, "/ping") end
  end

  test "result/2 reads empty, JSON and non-JSON bodies" do
    assert Transport.result(204, "") == {:ok, %{}}
    assert {:error, %Error{reason: :gateway, message: "<html>"}} = Transport.result(404, "<html>")
    assert {:error, %Error{reason: :bad_response, status: 200}} = Transport.result(200, "<html>")
  end

  test "a body Jason cannot encode is refused before anything is sent", %{name: name} do
    assert {:error, %Error{reason: :invalid, status: nil}} =
             Transport.request(name, :post, "/ping", %{"at" => {1, 2}})

    assert {:error, %Error{reason: :invalid}} = Transport.encode(%{"pid" => self()})
    assert Transport.encode(nil) == {:ok, nil}
  end
end
